export class Game {
  constructor(canvas, uiRoot) {
    this.canvas = canvas;
    this.uiRoot = uiRoot;
    const reviewId = new URLSearchParams(globalThis.location?.search || "").get("review");
    const preset = chapter1.reviewPresets?.[reviewId];
