  if (!browserAvailable(t, chromium.executablePath())) return;

  const port = await availablePort();
  const server = spawn(process.execPath, ["tools/dev-server.mjs"], {
    cwd: projectRoot,
    env: { ...process.env, PORT: String(port) },
    stdio: ["ignore", "pipe", "pipe"]
  });
  let serverOutput = "";
